import { Film, Scissors, Aperture, Sparkles } from 'lucide-react';
import { FadeUp } from './Reveal';

const SERVICE_IMG =
  'https://images.pexels.com/photos/10395639/pexels-photo-10395639.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=900&w=700';

const services = [
  { icon: Film, no: '01', title: 'Direction', desc: 'Story-driven direction that puts performance and mood above spectacle.' },
  { icon: Aperture, no: '02', title: 'Cinematography', desc: 'Natural-light framing and deliberate camera language for every scene.' },
  { icon: Scissors, no: '03', title: 'Editing', desc: 'Rhythm-first cuts, sound design and colour that shape the final feel.' },
  { icon: Sparkles, no: '04', title: 'VFX & Post', desc: 'Practical-first visual effects and grading that stay invisible.' },
];

export const Services = () => {
  return (
    <section id="services" className="relative px-6 md:px-12 py-28 md:py-40">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        <div className="lg:col-span-4">
          <FadeUp>
            <span className="text-[11px] tracking-[0.3em] uppercase text-[#E11D48]">[ Services ]</span>
            <h2 className="font-display font-semibold text-5xl md:text-6xl uppercase leading-[0.95] mt-5">
              What we<br />do on set
            </h2>
            <p className="mt-6 text-white/60 max-w-sm leading-relaxed">
              A full independent pipeline — from the first draft to the final export.
            </p>
          </FadeUp>
          <FadeUp delay={0.15}>
            <div className="mt-10 relative overflow-hidden group">
              <img
                src={SERVICE_IMG}
                alt="Cinema camera"
                className="w-full h-64 object-cover group-hover:scale-105 transition-transform duration-700"
              />
              <div className="absolute inset-0 bg-black/30" />
            </div>
          </FadeUp>
        </div>

        <div className="lg:col-span-7 lg:col-start-6 grid grid-cols-1 sm:grid-cols-2 gap-px bg-white/10">
          {services.map((s, i) => {
            const Icon = s.icon;
            return (
              <FadeUp key={s.title} delay={i * 0.08} className="h-full">
                <div className="group relative h-full bg-[#050505] p-8 md:p-10 overflow-hidden transition-colors duration-500 hover:bg-[#0d0d0d]">
                  <span
                    className="absolute -right-4 -top-6 font-display font-semibold text-[6rem] text-white/[0.04] group-hover:text-[#E11D48]/10 transition-colors duration-500"
                  >
                    {s.no}
                  </span>
                  <Icon className="w-7 h-7 text-[#E11D48] mb-8" strokeWidth={1.4} />
                  <h3 className="font-display font-medium text-2xl uppercase">{s.title}</h3>
                  <p className="mt-4 text-sm text-white/55 leading-relaxed">{s.desc}</p>
                  <span className="absolute bottom-0 left-0 h-px w-0 bg-[#E11D48] group-hover:w-full transition-all duration-500" />
                </div>
              </FadeUp>
            );
          })}
        </div>
      </div>
    </section>
  );
};
